_CORE_SRC = '# Exact action format: {"moves": [(from_node, to_node, count), ...], "build": n_buy}\n# Payout: equal fleets split proportionally to capacity; otherwise the larger fleet\n# serves min(4 * fleet, demand) first, and the smaller serves the remainder.\n# Profit = revenue - 2.0 * drones away from own base - 15.0 * drones bought.\nimport time\nimport heapq\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 120\nMAX_DRONES = 40\nBUILD_COST = 15.0\n\n\ndef served(a, b, demand):\n    if demand <= 0.0 or a <= 0:\n        return 0.0\n    if a == b:\n        return 4.0 * a * demand / max(4.0 * (a + b), demand)\n    if a > b:\n        return min(4.0 * a, demand)\n    return min(4.0 * a, max(0.0, demand - 4.0 * b))\n\n\ndef preprocess_map(n, edges):\n    adj = [[] for _ in range(n)]\n    for u, v in edges:\n        adj[u].append(v)\n        adj[v].append(u)\n    for row in adj:\n        row.sort()\n    distances = []\n    for s in range(n):\n        d = [n + 1] * n\n        d[s] = 0\n        queue = deque([s])\n        while queue:\n            u = queue.popleft()\n            for v in adj[u]:\n                if d[v] > n:\n                    d[v] = d[u] + 1\n                    queue.append(v)\n        distances.append(d)\n    return adj, distances\n\n\ndef legal_action(have, want, base, adj, distances, build, money):\n    surplus = [max(0, have[i] - want[i]) for i in range(len(have))]\n    deficit = [max(0, want[i] - have[i]) for i in range(len(have))]\n    pairs = sorted(\n        (distances[s][t], s, t)\n        for s in range(len(have)) if surplus[s]\n        for t in range(len(have)) if deficit[t] and s != t\n    )\n    combined = {}\n    for distance, s, t in pairs:\n        count = min(surplus[s], deficit[t])\n        if not count:\n            continue\n        hops = [v for v in adj[s] if distances[v][t] == distance - 1]\n        if not hops:\n            continue\n        # Prefer an intermediate node with a deficit.\n        hop = min(hops, key=lambda v: (-deficit[v], v))\n        surplus[s] -= count\n        deficit[t] -= count\n        combined[s, hop] = combined.get((s, hop), 0) + count\n\n    available = list(have)\n    moves = []\n    for (s, t), count in sorted(combined.items()):\n        count = min(int(count), available[s])\n        if count > 0 and t in adj[s]:\n            moves.append((int(s), int(t), int(count)))\n            available[s] -= count\n    affordable = max(0, int(max(0.0, money) // BUILD_COST))\n    build = max(0, min(int(build), MAX_DRONES - sum(have), affordable))\n    return {"moves": moves, "build": int(build)}\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.adj = None\n        self.distances = None\n        self.sums = []\n        self.low = []\n        self.high = []\n        self.samples = 0\n        self.last_turn = None\n        self.enemy = []\n        self.seen = []\n        self.previous = []\n        self.bad_reports = 0\n\n    def update_estimates(self, obs):\n        n = obs["n_nodes"]\n        turn = obs["turn"]\n        if self.last_turn != turn:\n            self.samples += 1\n            for v, demand in enumerate(obs["demand"]):\n                self.sums[v] += demand\n                self.low[v] = max(self.low[v], (demand - 0.05) / 1.5)\n                self.high[v] = min(self.high[v], (demand + 0.05) / 0.5)\n            self.last_turn = turn\n        means = []\n        for v in range(n):\n            lo, hi = self.low[v], self.high[v]\n            if hi < lo:\n                hi = lo\n            empirical = self.sums[v] / max(1, self.samples)\n            midpoint = (lo + hi) / 2.0\n            means.append(min(hi, max(lo, 0.3 * empirical + 0.7 * midpoint)))\n        opponent = []\n        for v, count in enumerate(obs["opponent_drones"]):\n            if count is not None:\n                self.enemy[v] = int(count)\n                self.seen[v] = turn\n            # Retain recent sightings rather than interpreting fog as empty space.\n            age = turn - self.seen[v]\n            opponent.append(self.enemy[v] if age <= 10 else 0)\n        return means, opponent\n\n    def plan(self, obs, means, opponent, deadline):\n        n = obs["n_nodes"]\n        base = obs["player_base"]\n        other_base = obs["opponent_base"]\n        have = list(obs["player_drones"])\n        total = sum(have)\n        remaining = max(1, N_TURNS - obs["turn"])\n        horizon = min(remaining, 26)\n        limit = min(MAX_DRONES, total + 4)\n        future = []\n        immediate = []\n        own_future = []\n        for v in range(n):\n            demands = [means[v] * (0.5 + (j + 0.5) / 9.0) for j in range(9)]\n            b = opponent[v]\n            baseline = sum(served(b, 0, d) for d in demands) / 9.0\n            baseline_now = served(b, 0, obs["demand"][v])\n            f, now, own = [], [], []\n            for a in range(limit + 1):\n                income = sum(served(a, b, d) for d in demands) / 9.0\n                denial = baseline - sum(served(b, a, d) for d in demands) / 9.0\n                f.append(income + denial - 2.0 * a)\n                own.append(income - 2.0 * a)\n                d = obs["demand"][v]\n                now.append(served(a, b, d) + baseline_now - served(b, a, d) - 2.0 * a)\n            future.append(f)\n            immediate.append(now)\n            own_future.append(own)\n\n        pool = have[:]\n        want = [0] * n\n        # Bundles handle the non-concave jump when we exceed an opposing fleet.\n        while sum(pool) and time.perf_counter() < deadline:\n            heap = []\n            for v in range(n):\n                if v == base or v == other_base:\n                    continue\n                k = want[v]\n                sources = sorted(\n                    (self.distances[s][v], s)\n                    for s in range(n) if pool[s]\n                )\n                chosen = []\n                for distance, s in sources:\n                    chosen.extend([(distance, s)] * min(pool[s], 7 - len(chosen)))\n                    if len(chosen) >= 7:\n                        break\n                cost = 0.0\n                sticky = 0.0\n                for size, (distance, s) in enumerate(chosen, 1):\n                    if k + size > limit:\n                        break\n                    cost += 2.0 * max(0, distance - 1)\n                    if distance > 0:\n                        cost += max(0, distance - 1) * max(\n                            0.0, future[v][k + size] - future[v][k + size - 1]\n                        )\n                    sticky += 0.5 if k + size <= self.previous[v] else 0.0\n                    gain = horizon * (future[v][k + size] - future[v][k]) - cost\n                    # Current demand is known only for drones arriving this turn.\n                    if all(d <= 1 for d, _ in chosen[:size]):\n                        gain += (immediate[v][k + size] - immediate[v][k]\n                                 - future[v][k + size] + future[v][k])\n                    if max(d for d, _ in chosen[:size]) > remaining:\n                        continue\n                    gain += sticky\n                    if gain > 0.2 * size:\n                        heapq.heappush(heap, (-gain / size, v, size, chosen[:size]))\n            if not heap:\n                break\n            _, v, size, chosen = heapq.heappop(heap)\n            want[v] += size\n            for _, source in chosen:\n                pool[source] -= 1\n\n        want[base] += sum(pool)\n        build = 0\n        # Buy only when an extra bundle has a clear, self-financing payback.\n        if remaining > 20 and sum(pool) == 0 and total < MAX_DRONES:\n            money = obs.get("player_money", 0.0)\n            max_buy = min(3, MAX_DRONES - total, max(0, int(money // BUILD_COST)))\n            best = 0.0\n            for v in range(n):\n                if v in (base, other_base):\n                    continue\n                delay = self.distances[base][v] + 1\n                productive = min(remaining - delay, 32)\n                k = want[v]\n                for b in range(1, max_buy + 1):\n                    if k + b > limit or productive <= 0:\n                        continue\n                    travel = 2.0 * b * max(0, delay - 2)\n                    value = productive * (own_future[v][k + b] - own_future[v][k])\n                    net = value - travel - BUILD_COST * b\n                    if net > best + 5.0:\n                        best, build = net, b\n        return want, build\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, TIME_BUDGET) * 0.56\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return {"moves": [], "build": 0}\n        if self.adj is None:\n            self.adj, self.distances = preprocess_map(n, obs.get("edges", []))\n            self.sums = [0.0] * n\n            self.low = [1.0] * n\n            self.high = [10.0] * n\n            self.enemy = [0] * n\n            self.seen = [-1000] * n\n            self.previous = [0] * n\n        if (obs.get("n_invalid_actions_last_turn", 0) > 0\n                or not obs.get("action_format_correct_last_turn", True)):\n            self.bad_reports += 1\n        means, opponent = self.update_estimates(obs)\n        want, build = self.plan(obs, means, opponent, deadline)\n        if self.bad_reports >= 2:\n            build = 0\n        action = legal_action(\n            obs["player_drones"], want, obs["player_base"],\n            self.adj, self.distances, build, obs.get("player_money", 0.0)\n        )\n        self.previous = want[:]\n        return action\n'
_CORE_CLASS = 'Strategy'
_FALLBACK_SRC = None
_FALLBACK_CLASS = 'Strategy'
